def _extract_creators(self) -> Dict[str, Any]:
    citation_authors = self.meta.all("citation_author")
    citation_institutions = self.meta.all("citation_author_institution")
    dc_authors = self.meta.all("DC.Creator.PersonalName")
    orcids = self.meta.all("citation_author_orcid")

    creators: List[Creator] = []
    raw = {
        "citation_author": citation_authors,
        "citation_author_institution": citation_institutions,
        "citation_author_orcid": orcids,
        "DC.Creator.PersonalName": dc_authors,
    }

    if citation_authors:
        if citation_institutions and len(citation_institutions) != len(citation_authors):
            self._warn(
                code="CITATION_AUTHOR_INSTITUTION_COUNT_MISMATCH",
                message=f"citation_author_institution count ({len(citation_institutions)}) does not match citation_author count ({len(citation_authors)}); institutions paired only by shared index.",
                function_name="_extract_creators",
                context={
                    "citation_author_count": len(citation_authors),
                    "citation_author_institution_count": len(citation_institutions),
                },
            )
        for idx, author in enumerate(citation_authors):
            given, family = split_name(author)
            affiliations: List[str] = []
            if idx < len(citation_institutions):
                aff = normalize_space(citation_institutions[idx])
                if aff:
                    affiliations.append(aff)
            name_ids: List[Dict[str, Any]] = []
            if idx < len(orcids):
                orcid = normalize_space(orcids[idx])
                if orcid:
                    name_ids.append({"nameIdentifier": orcid, "nameIdentifierScheme": "ORCID", "schemeURI": "https://orcid.org"})
            creators.append(Creator(
                creatorName=author,
                givenName=given,
                familyName=family,
                affiliations=affiliations,
                nameIdentifiers=name_ids,
                source="meta:citation_author(+citation_author_institution/+citation_author_orcid)",
            ))
        return {"items": [asdict(c) for c in creators], "raw": raw}

    if dc_authors:
        for author in dc_authors:
            given, family = split_name(author)
            creators.append(Creator(creatorName=author, givenName=given, familyName=family, source="meta:DC.Creator.PersonalName"))
        return {"items": [asdict(c) for c in creators], "raw": raw}

    names = self._texts("ul.authors-string li span")
    affs = self._texts("div.article-details__author-affiliation")
    if affs and len(affs) != len(names):
        self._warn(
            code="DOM_AFFILIATION_COUNT_MISMATCH",
            message=f"DOM affiliation count ({len(affs)}) does not match DOM author count ({len(names)}); affiliations paired only by shared index.",
            function_name="_extract_creators",
            context={"dom_author_count": len(names), "dom_affiliation_count": len(affs)},
        )
    for idx, name in enumerate(names):
        given, family = split_name(name)
        affiliations = [affs[idx]] if idx < len(affs) and affs[idx] else []
        creators.append(Creator(
            creatorName=name,
            givenName=given,
            familyName=family,
            affiliations=affiliations,
            source="dom:authors-string/article-details__author-affiliation",
        ))
    return {"items": [asdict(c) for c in creators], "raw": raw}
